import {W} from './worked.js';
export const exercises=[
{title:'Trễ truyền cuộn thư',prompt:'Gói 1250 byte truyền qua liên kết 1 Mbps. Trễ truyền là bao nhiêu ms?',answer:10,unit:'ms',steps:'L = 1250 × 8 = 10000 bit. d_trans = L/R = 10000/1000000 = 0,01 s = 10 ms.',ch:0,pages:[16,17]},
{title:'Độ trễ hai trạm',prompt:'Một gói 1000 byte qua 2 liên kết cùng 1 Mbps. Mỗi liên kết dài 100 km, tốc độ lan truyền 2×10⁸ m/s. Bỏ qua hàng đợi và xử lý. Tổng trễ là bao nhiêu ms?',answer:17,unit:'ms',steps:'Trễ truyền mỗi link = 8 ms. Trễ lan truyền mỗi link = 100000/(2×10⁸) = 0,5 ms. Tổng = 2 × (8+0,5) = 17 ms.',ch:0,pages:[16,17]},
{title:'Nút thắt đưa thư',prompt:'Tuyến không tắc nghẽn gồm liên kết 500 Kbps, 2 Mbps và 1 Mbps. Thông lượng lý tưởng là bao nhiêu Kbps?',answer:500,unit:'Kbps',steps:'Quy về Kbps: 500, 2000, 1000. Liên kết chậm nhất quyết định: min = 500 Kbps.',ch:0,pages:[17,27]},
{title:'Header UDP',prompt:'Một UDP segment có length 28 byte. Phần dữ liệu dài bao nhiêu byte?',answer:20,unit:'byte',steps:'Length gồm header và dữ liệu. Header UDP dài 8 byte, nên dữ liệu = 28−8 = 20 byte.',ch:2,pages:[17,18]},
{title:'ACK tiếp theo',prompt:'TCP đã nhận liên tục tất cả byte từ 1000 đến 1499. Chưa nhận byte 1500. Giá trị ACK tiếp theo là bao nhiêu?',answer:1500,unit:'số thứ tự byte',steps:'ACK là số thứ tự byte mong đợi tiếp theo, nên ACK = 1500, không phải số byte vừa nhận.',ch:2,pages:[51,52]},
{title:'Số host của khu vực',prompt:'Một subnet /27 thông thường có bao nhiêu địa chỉ host dùng được (loại địa chỉ mạng và broadcast)?',answer:30,unit:'host',steps:'Số bit host = 32−27 = 5. Tổng địa chỉ 2⁵ = 32. Host dùng được = 32−2 = 30.',ch:3,pages:[24,27]},
{title:'Mượn bit chia mạng',prompt:'Chia mạng /24 thành ít nhất 6 subnet bằng nhau. Prefix mới nhỏ nhất là bao nhiêu? Nhập số sau dấu /.',answer:27,unit:'prefix',steps:'Cần s sao cho 2ˢ ≥ 6. s = 3 tạo 8 subnet. Prefix mới = 24+3 = /27.',ch:3,pages:[24,30]},
{title:'Offset mảnh thứ hai',prompt:'Datagram 4000 byte, header 20 byte, MTU 1500 byte. Fragment offset của mảnh thứ hai là bao nhiêu?',answer:185,unit:'đơn vị 8 byte',steps:'Mảnh đầu mang 1480 byte dữ liệu (bội 8). Offset mảnh hai = 1480/8 = 185.',ch:3,pages:[47,48]},
{title:'Số mảnh cần gửi',prompt:'IPv4 datagram 3000 byte (đã gồm header 20 byte), MTU 500 byte, DF=0, header mỗi mảnh 20 byte. Sinh ra bao nhiêu mảnh?',answer:7,unit:'mảnh',steps:'Payload gốc 2980 byte. Dữ liệu mảnh không cuối = floor((500−20)/8)×8 = 480 byte. 2980 = 6×480 + 100. Vậy có 7 mảnh.',ch:3,pages:[47,48]},
{title:'Tìm đường ngắn',prompt:'Ba trạm A, B, C có chi phí liên kết A–B=2, B–C=1, A–C=7. Chi phí đường ngắn nhất A tới C là bao nhiêu?',answer:3,unit:'đơn vị chi phí',steps:'Trực tiếp A–C tốn 7. Qua B: 2+1=3. min(7,3)=3, đường A–B–C.',ch:3,pages:[68,79]}
];
const details=[
W('Gói 1250 byte; R=1 Mbps.','L: độ dài bit; R: bit/s; t_trans: giây.','L=1250×8=10000 bit; R=10⁶ bit/s.','t_trans=L/R','t_trans=10000/10⁶=0,01 s','10 ms'),
W('1000 byte/gói; N=2 link; R=1 Mbps; d=100 km/link; s=2×10⁸ m/s.','N: link; L: bit/gói; R: bit/s; d: mét; s: m/s.','L=8000 bit; R=10⁶ bit/s; d=100000 m.','T=N(L/R+d/s)','T=2(8000/10⁶+100000/(2×10⁸))=0,017 s','17 ms'),
W('R₁=500 Kbps; R₂=2 Mbps; R₃=1 Mbps; không cạnh tranh.','R_i: tốc độ link; Tput: thông lượng.','Quy về Kbps: 500, 2000, 1000.','Tput=min(R₁,R₂,R₃)','min(500,2000,1000)','500 Kbps'),
W('UDP length T=28 byte.','T: cả segment; H: header; D: dữ liệu.','H=8 byte; không đổi đơn vị.','D=T−H','D=28−8','20 byte'),
W('Đã nhận liên tục byte 1000–1499; byte 1500 chưa tới.','b: byte cuối đoạn đã đủ; ACK: byte mong đợi.','Số thứ tự byte, không phải số byte vừa nhận.','ACK=b+1','ACK=1499+1','1500'),
W('Subnet /27 thông thường.','p: prefix; h: bit host; U: host dùng được.','h=32−27=5.','U=2^h−2','U=2⁵−2=32−2','30 host'),
W('Prefix cũ /24; cần ≥6 subnet bằng nhau.','s: bit mượn; p_new: prefix mới.','2²=4<6≤8=2³, nên s=3.','s=ceil(log₂6); p_new=24+s','p_new=24+3','/27 (tạo 8 subnet)'),
W('IPv4 total=4000 byte, H=20 byte, MTU=1500 byte.','H: header; D₁: dữ liệu mảnh đầu; o₂: offset mảnh hai.','Offset dùng đơn vị 8 byte; 1480 là bội 8.','D₁=floor((MTU−H)/8)×8; o₂=D₁/8','D₁=floor((1500−20)/8)×8=1480; o₂=1480/8','185'),
W('Total=3000 byte; H=20 byte; MTU=500 byte; DF=0.','D: payload gốc; C: payload/mảnh không cuối; n: số mảnh.','D=3000−20=2980 byte; C=floor((500−20)/8)×8=480 byte.','n=ceil(D/C)','n=ceil(2980/480)=ceil(6,20833…)','7 mảnh'),
W('A–B=2; B–C=1; A–C=7, đồ thị vô hướng.','c: chi phí liên kết; D(A,C): chi phí tối ưu.','Chi phí cùng đơn vị; không đổi.','D(A,C)=min(c(A,C),c(A,B)+c(B,C))','min(7,2+1)=min(7,3)','3, qua A–B–C')];
exercises.forEach((e,i)=>Object.assign(e,{id:'e'+i,worked:details[i],grading:{integer:!['ms','Kbps'].includes(e.unit),absTol:['ms','Kbps'].includes(e.unit)?0.01:0,relTol:0}}));
exercises.push({id:'e10',ch:1,pages:[28,29],title:'HTTP: đổi RTT sang giây',prompt:'Một đối tượng non-persistent HTTP, RTT=25 ms; thời gian phát nội dung 0,5 ms. Bỏ DNS và chi phí khác. Tính 2RTT+t_trans bằng giây.',answer:0.0505,unit:'s',grading:{absTol:0.000005,relTol:0},worked:W('RTT=25 ms; t_trans=0,5 ms.','RTT: đi-về; t_trans: phát nội dung; T: tổng thời gian.','RTT=0,025 s; t_trans=0,0005 s.','T=2RTT+t_trans','T=2×0,025+0,0005','0,0505 s'),steps:'RTT=0,025 s; t_trans=0,0005 s. T=2RTT+t_trans=0,0505 s.'},
{id:'e11',ch:2,pages:[37,38],title:'Hiệu suất stop-and-wait',prompt:'Link 1 Gbps, gói 8000 bit, RTT=30 ms. Bỏ phát ACK. Tính U=(L/R)/(RTT+L/R) theo phần trăm, làm tròn 5 chữ số thập phân.',answer:8000/1e9/(.03+8000/1e9)*100,unit:'%',grading:{absTol:0.000005,relTol:0},worked:W('R=1 Gbps; L=8000 bit; RTT=30 ms.','R: bit/s; L: bit; U: tỷ lệ sử dụng sender.','R=10⁹ bit/s; RTT=0,03 s; L/R=0,000008 s.','U=(L/R)/(RTT+L/R)×100%','U=0,000008/(0,03+0,000008)×100%','≈0,02666%'),steps:'L/R=0,000008 s; RTT=0,03 s. U≈0,02666%.'});
